<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Domain;

/**
 * Result produced by the rendering engine: fully substituted subject, HTML body, optional
 * plain-text body, and associated assets.
 */
class RenderedTemplate
{
    /**
     * @param RenderedAsset[] $assets
     */
    public function __construct(
        private readonly string $htmlContent,
        private readonly ?string $subject = null,
        private readonly ?string $textContent = null,
        private readonly array $assets = [],
    ) {
    }

    /** Rendered HTML body. Always present. */
    public function htmlContent(): string
    {
        return $this->htmlContent;
    }

    /** Email subject. Null when the channel does not use it (e.g. SMS). */
    public function getSubject(): ?string
    {
        return $this->subject;
    }

    /** Rendered plain-text body. Null when the template version has no text content. */
    public function getTextContent(): ?string
    {
        return $this->textContent;
    }

    /**
     * Assets associated with this rendered document (e.g. stylesheets).
     * Assets with isEmbedded() = true are already inlined into htmlContent
     * and do not need to be linked externally.
     *
     * @return RenderedAsset[]
     */
    public function assets(): array
    {
        return $this->assets;
    }
}
